import java.util.concurrent.atomic.AtomicLong;public class ParallelSum{public static void main(String[]x)throws Exception{int[] a=new int[100000];java.util.Arrays.fill(a,1);AtomicLong sum=new AtomicLong();Thread[] ts=new Thread[4];for(int k=0;k<4;k++){final int lo=k*a.length/4,hi=(k+1)*a.length/4;ts[k]=new Thread(()->{long local=0;for(int i=lo;i<hi;i++)local+=a[i];sum.addAndGet(local);});ts[k].start();}for(Thread t:ts)t.join();System.out.println("Sum="+sum.get());}}
